An issue arises because `col_suffixes` contains empty strings (e.g. `""`) for ascending columns, causing `IndexColumns` to append a space even when the suffix is empty. We can check that the suffix is truthy before appending it.

Here is the minimal code change to resolve the issue:

### File: django/db/backends/ddl_references.py
<<<<<<< SEARCH
class IndexColumns(Columns):
    def __init__(self, table, columns, quote_name, col_suffixes=(), opclasses=()):
        self.opclasses = opclasses
        super().__init__(table, columns, quote_name, col_suffixes)

    def __str__(self):
        def col_str(column, idx):
            # Index.__init__() guarantees that self.opclasses is the same
            # length as self.columns.
            col = '{} {}'.format(self.quote_name(column), self.opclasses[idx])
            try:
                col = '{} {}'.format(col, self.col_suffixes[idx])
            except IndexError:
                pass
            return col

        return ', '.join(col_str(column, idx) for idx, column in enumerate(self.columns))
=======
class IndexColumns(Columns):
    def __init__(self, table, columns, quote_name, col_suffixes=(), opclasses=()):
        self.opclasses = opclasses
        super().__init__(table, columns, quote_name, col_suffixes)

    def __str__(self):
        def col_str(column, idx):
            # Index.__init__() guarantees that self.opclasses is the same
            # length as self.columns.
            col = '{} {}'.format(self.quote_name(column), self.opclasses[idx])
            try:
                col_suffix = self.col_suffixes[idx]
            except IndexError:
                pass
            else:
                if col_suffix:
                    col = '{} {}'.format(col, col_suffix)
            return col

        return ', '.join(col_str(column, idx) for idx, column in enumerate(self.columns))
